INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt1697116', 'Summer Camp Gator', NULL, 'PELICULA', 'Billy gets a call from Twin Lakes Summer camp about a gator problem. The camp fears that this gator might hurt the children, the dogs, or even the ducks. When Billy actually finds the gator he discovers it is almost nine feet long! Next, Billy and Ricky get called about an armadillo ransacking a prayer garden at a church.', '2010-01-01', 'https://m.media-amazon.com/images/M/MV5BMTcwNDQzMjY5OV5BMl5BanBnXkFtZTgwNjQ0NjM0MjE@._V1_.jpg');
