INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt1394374', 'Sie', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm1367645'), 'PELICULA', 'A consciously modern depiction of working women in East Germany - labourers and managers in a garment factory talk about relationships and family planning, raising children and career qualifications, women''s rights and equality in the socialist (meritocratic) society. In conversations with a doctor, the women also have a chance to voice their personal concerns, as well as their feelings about the birth control pill, a subject that caused a stir at the time.', '1970-01-01', 'https://m.media-amazon.com/images/M/MV5BMTVhZWI2NjAtOTJlYS00MGYzLTg1OGItN2I1ZmZiMzU2MWFjXkEyXkFqcGc@._V1_.jpg');
