INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0093968', 'Axiliad', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0504583'), 'PELICULA', 'A young, idealistic poet turns his back on civilization and goes to a small, backwoods village, rents a bed in the house of an old woman, and decides to make his living as a lumberjack. He soon realizes that the world around him is far from perfect. He does not make any real contact with the people in the village. An then another outcast like him rents a bed in the same house.', '1986-01-01', 'https://m.media-amazon.com/images/M/MV5BYmQ1N2U3YzktMjQyOC00ZGRiLTk4MzEtZGRiYzM4NTYxMzJmXkEyXkFqcGc@._V1_.jpg');
