INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0345998', 'Tempe Tip', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0707781'), 'PELICULA', 'Everyone dreams of finding the pot of gold at the end of the rainbow. For Max his search began when he fell into a hole in the ground in his own backyard. But you can''t keep something like this quiet for very long, especially not from an assortment of neighbours who just want to help. It becomes a quest to rival the Holy Grail and our battling crusaders are in control for the first time in their lives until luck and a stormwater drain change the course of events.', '2002-01-01', 'https://m.media-amazon.com/images/M/MV5BNmRkOGVjOTUtMGY1Mi00MzllLTkxM2UtYTNiNjJiOWE4ZmM4XkEyXkFqcGc@._V1_.jpg');
