INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0677442', 'The End of Time: Part 1', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0757084'), 'PELICULA', 'Ransick prepares to attack the city. Alex orders the TF rangers to return to the future, the crystals are causing disruptions, if they don''t leave they might not be able to return to their own time, he tells them Wes has to stay in his own time. The Rangers refuse, and try to prevent the attack. Wes knows his friends can''t stay in the present, and has a plan to send them back to their own time', '2001-01-01', 'https://m.media-amazon.com/images/M/MV5BMTA1MDg2NzEzNTdeQTJeQWpwZ15BbWU4MDUwODg1NjIx._V1_.jpg');
