INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt2387571', 'Taking on Tarmageddon', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm5034353'), 'PELICULA', 'Taking on Tarmageddon follows two groups of young campaigners on an emotional journey exploring the human cost of the biggest industrial project on the planet: the Canadian Tar Sands. The tar sands cover an area the size of England & Wales and produce 3-5 times the emissions of conventional oil. Living in the heart of this are Canada''s First Nation communities whose lands and rights have been trampled on by the tar sands.', '2012-01-01', 'https://m.media-amazon.com/images/M/MV5BNmEzN2E0NTMtOGFmOC00MGQxLWI5YjEtMDM5YWZiZGExNjgyXkEyXkFqcGc@._V1_.jpg');
