INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt7380680', 'É Quase Verdade', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm9277284'), 'PELICULA', 'Aparício is a beggar who lives in the streets of São Paulo. Together with his friends he is interviewed by a film crew and wants to know why Brazilian Cinema only shows abroad the very same themes and ideas. Ready to be a part of this stardom system he mercilessly questions his interlocutors until fabulous news changes his life forever.', '2014-01-01', 'https://m.media-amazon.com/images/M/MV5BOTI5YzdmYzMtZjIzYS00NDU1LWI1OTAtOTYwMGFlMzZmMzU1XkEyXkFqcGc@._V1_.jpg');
