INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt1407939', 'Bakhita', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0133075'), 'PELICULA', 'Bakhita is captured as a slave as a child, a Viennian man sees her. Many years later the man has returned to do business and recognizes her. After saving her, he takes her back to his home. The other servants think she''s the devil due to her black skin, but the daughter of the house chooses her as her nanny.', '2009-01-01', 'https://m.media-amazon.com/images/M/MV5BYWQ3NjkzMTUtNmM1Ni00ZDQzLTg1MWItOWEyNGNmZTJjOWUzXkEyXkFqcGc@._V1_.jpg');
