INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt1122798', 'At Home in the Water', NULL, 'PELICULA', 'Here we have a demonstration by one of the world''s greatest exponents of swimming, M.G.H. Corsan. And this demonstration is not in the confines of a tank, but on the shore of Lake George. Mr. Corsan shows us the most approved methods of life-saving, and after marveling at his own work, we are left to admire some of the feats of two of his most advanced pupils, a young man and a girl. How these two paddle safely off in an apparently submerged canoe is a sight worth going a long way to see.', '1912-01-01', 'https://m.media-amazon.com/images/M/MV5BMTQ3NTk4ODgtZTY3Zi00MDgwLWFlYzktZDllZDRlNTg1MzcxXkEyXkFqcGc@._V1_.jpg');
