INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0321432', 'Beyond the Seventh Door', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0070837'), 'PELICULA', 'After meeting up with his ex-lover Wendy, an ex-convict and thief named Boris gets persuaded to do one more heist. He is supposed to help Wendy rob her paraplegic, millionaire boss Lord Breston, for whom she has been working as a housemaid. But things turn out to be much more complicated than expected, in this exciting horror thriller with a twist ending.', '1987-01-01', 'https://m.media-amazon.com/images/M/MV5BNjNhNjRhNzctYTFkYi00MzdhLWFhOGQtZGNiYmJkNjY4NjM3XkEyXkFqcGc@._V1_.jpg');
