INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt1318024', 'Hard Lesbian: Quick & Deep', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm3116083'), 'PELICULA', 'Reiko, engaged to her boyfriend, Aki, meets a lesbian girl on a train who opens her up to the lesbian world. Reiko finds herself attracted to the girl, and is forced to make a difficult decision about her fiancé. The film touches upon the delicate question of social acceptance of alternative lifestyles in the closed Japanese society of today. Directed by Osamu Sato Starring Kyoko Natsume, Nancy and Kyoko Hayami. Running time: 64 minutes.', '2005-01-01', 'https://m.media-amazon.com/images/M/MV5BMjA0Mjg1NzQ3NV5BMl5BanBnXkFtZTgwNTE0NjM3NzE@._V1_.jpg');
