INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt1522203', 'Nightfur', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm1022583'), 'PELICULA', 'Nightfur is a campy, new wave science fiction film. An introspective astrophysics major visits a remote lab to work with his mentor, Dr. Roberts. After his arrival, he finds that a young woman has been taken in by the doctor. She is found to be sensitive to a mysterious signal coming from the depths of space. The unexplainable phenomena that occur force her new friends to look at life from a different, unscientific, angle. When Helen''s forest dwelling spiritual guide enters the mix they find that logic, love, and jealousy become easily entangled in the presence of the unknown.', '2011-01-01', 'https://m.media-amazon.com/images/M/MV5BMTQ4MDMyOTQxNF5BMl5BanBnXkFtZTcwNjgwNjYwNw@@._V1_.jpg');
