INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt2291996', 'The Vatican Museums', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm5881982'), 'PELICULA', 'Originally produced in 1997 on the threshold of the Third Millennium of the Christian Era, and in celebration of the Jubilee of the Year of Our Lord 2000, The Vatican Museums was the culmination of three years of research and filming, the collaboration of thirty-two scholars and historians from around the world, a crew of forty directors of photography, operators, and lighting technicians, state-of-the-art digital cinematography, lighting, animation, and computerized editing, and the work of a famous composer with original performances by master musicians. Now available on DVD for the first time, this historic three-disc collection features seven hours of magnificent documentary film that illuminates and chronicles the great journey of the human spirit. Here then is the world''s most spectacular and sacred repository of art, history, and faith.', '2007-01-01', 'https://m.media-amazon.com/images/M/MV5BMTM5NzMwOTQxMF5BMl5BanBnXkFtZTgwMjUwNzA2MDE@._V1_.jpg');
