INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt1792588', 'The Big 4: Live from Sofia, Bulgaria', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0926911'), 'PELICULA', 'In 2010, for the first time ever, four giants of metal shared one stage for seven European shows. "Big Four," Metallica, Slayer, Megadeth and Anthrax, the final night, at the Sonisphere Festival in Sofia, Bulgaria, was broadcast live via satellite to movie screens around the world. Now this historic concert is available on your screen... which means the best seat in the house is now in your house.', '2010-01-01', 'https://m.media-amazon.com/images/M/MV5BZTFhYmJlODMtMjE3MS00NTg0LWE5ZmQtYTYzOWIwNGNiNDM0XkEyXkFqcGc@._V1_.jpg');
