INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0633025', 'Home Again: Part 1', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0001446'), 'PELICULA', 'Albert has fallen in with the wrong crowd so Charles quits his job and takes him home to Walnut Grove. Unfortunately, part of Albert''s problem is that he has gotten addicted to morphine and he steals some from Doc Baker so the problems persist.', '1983-01-01', 'https://m.media-amazon.com/images/M/MV5BMzA3NDFmOGYtNmY2ZC00ZjY2LWIxNzUtNzZkZTE5ZWNkYTU1XkEyXkFqcGc@._V1_.jpg');
