INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt3052110', 'Oh, My God!', NULL, 'PELICULA', 'The protagonist, who used to be a high-school teacher and now a company man who lost directions of his life, dies by being involved in a stranger''s suicide. When opened his eyes there was the h... it was far from the heaven, he was surrounded by half naked men dancing around him. Their leader comes closer to him and tells him that he was given a chance to revive because he saved the suicide''s life. However, the leader also tells him that his life can be restored only if he succeeded a mission. The mission he was told was...', '2013-01-01', NULL);
