INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt2145707', 'En Passant', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm3630762'), 'PELICULA', 'Since the day of the accident all Laurie can do is drink. Oh sure, she goes through the motions and participates in the day to day doldrums of life but her soul has disappeared. This Hallows Eve, however, will give Laurie a taste of the other world and remind her that oblivion cannot be found in a bottle. Reality is no simple thing.', '2011-01-01', NULL);
