INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0275950', 'BMW Vermelho', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0684244'), 'PELICULA', 'This short is a tragic comedy about a poor unemployed worker, and his family, who live in a ''favela'' (Brazilian shantytown). He wins a brand new red BMW car and sees his life transformed. His survival, which was already difficult, becomes dramatic and quite extraordinary.', '2000-01-01', 'https://m.media-amazon.com/images/M/MV5BYTU4ZGJjMzUtYzQzYi00YzFhLWJmNTQtOTcxMTQ3Y2I3MzRjXkEyXkFqcGc@._V1_.jpg');
