INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0155672', 'The Disturbance at Dinner', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0015511'), 'PELICULA', 'Wilson Pomade, a totally insignificant but pleasant young man, has gone through life unnoticed and unrecognized by others until one day when he encounters the beautiful and elegant Marian Pronkridge, whose only flaw is her blindness. Wilson saves Marian''s life, but is overwhelmed by her beauty, unable to speak with her and runs away. However, fate or is it destiny...brings the two together again and they embark on a journey of personal discovery that culminates in a significant, yet unexpected twist in "The Disturbance at Dinner".', '1998-01-01', 'https://m.media-amazon.com/images/M/MV5BMTA0MDg4MjQ1NDReQTJeQWpwZ15BbWU2MDk4Nzc3OQ@@._V1_.jpg');
