INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0468133', 'Transients in Arcadia', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0444380'), 'PELICULA', 'Mamie is a New York shop-girl who saved for an entire year that she may pose at an exclusive Summer resort for one week as an aristocrat and perhaps win for herself a "Prince Charming.'''' Farrington is collector for an installment payment concern who is at the resort for the same purpose. A series of humorous incidents invariably throw them together. In the end when Farrington calls at the shop for Mamie''s installment each is revealed in his and her true character. They reveal their love for each other and start for a honeymoon at Coney Island.', '1925-01-01', 'https://m.media-amazon.com/images/M/MV5BZDA5NjBiOTAtMTEwYy00NWIwLThjZWItNGQ0NWNhOWUxNWI4XkEyXkFqcGc@._V1_.jpg');
