INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt1337130', 'Thinking...', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm2590626'), 'PELICULA', 'A young woman enters a silent, Buddhist, meditation retreat only to find the idea of a ''quiet mind'' impossible. As she sits, she journeys though a budding relationship from its innocent beginning to its sexually awakened end and continues from there into a world of chaos and confusion that could only exist in the imagination. ''thinking'' is the comical, back-and-forth struggle of distraction one experiences while trying not to be distracted.', '2008-01-01', 'https://m.media-amazon.com/images/M/MV5BM2JjYjNhMjEtMmMwNC00NTkxLTllNzItNThjZjlhYmI0YWNkXkEyXkFqcGc@._V1_.jpg');
