INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt7051528', 'They Come from the Center of the World', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm6674976'), 'PELICULA', 'I dream about the beast that lives at the bottom of the lake. Only few people have seen it. The air freezes when it''s is near you because it''s heart is too cold. They say you should not look it in the eyes, because your heart will freeze as well. Only one woman has looked the beast in the eyes, but her heart is sad and frozen long time ago.', '2017-01-01', 'https://m.media-amazon.com/images/M/MV5BNTk0MWU3ZmMtM2M0Mi00OGU4LWI2YTItYjgzYTIxNDFkYzUwXkEyXkFqcGc@._V1_.jpg');
