INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt8717856', 'Its Own Reward', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm8854491'), 'PELICULA', 'Caleb Williams lost everything when his father was killed by a band of bikers. Now 23 years old, Caleb tracks down the men that killed his father, and engages in a confrontation that will end his life, and possibly, his suffering.', '2019-01-01', 'https://m.media-amazon.com/images/M/MV5BNDQwZjRiNWItOTNlZi00ZjA3LTgxZGMtNDUyMTc4Y2I3NWFlXkEyXkFqcGc@._V1_.jpg');
