INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt1402405', 'Anupama', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0788908'), 'PELICULA', 'Anant and Anupama are neighbors in love with each other. None discloses their love for each other. Anupamas dad gets her married with alliance. In due course, young widower, Anupama comes home with a baby boy. Years go by without declare their love for each other. A young boy overhears the gossip of how Anant is always there for him and his mom. And that hurt the child and request Anant not come by anymore. At that time, they disclosed their love for each other. And Anant refuses to take step forward and walks away. In the end, Mom n the child runs behind the train, with Anant in it. And we see the kumkumma on the floor.', '1981-01-01', NULL);
