INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt5131360', 'Eco de Femmes', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm7668375'), 'PELICULA', 'Six women, Zina, Cherifa, Halima, Fatima, Mina and Jamila, who live in the rural areas of Morocco and Tunisia share their dreams and their fight for emancipation through their work. They''re connected by a common goal to achieve recognition for their professional identity and gender. They have created farming cooperatives where they combine their ancient knowledge with the development of new products for the local and international markets.', '2014-01-01', 'https://m.media-amazon.com/images/M/MV5BNjk1MjhiNDMtYTM4Yy00MTZhLTkzMWYtZTA3ZGE2ZDc0ZDQxXkEyXkFqcGc@._V1_.jpg');
